"use client"

import { useEffect, useState } from "react"
import { PortalShell, StateMessage } from "../../components/PortalShell"
import { api } from "../../lib/api"

type Settings = { id: string; name: string; imageUrl: string | null; contactPhone: string | null; contactEmail: string | null; address: string | null; upiId: string | null; paymentDisplayName: string | null; qrImageUrl: string | null; cashCollectionEnabled: boolean; upiCollectionEnabled: boolean; paymentInstructions: string | null }
type Identity = { vendor: { id: string } | null }

export default function VendorSettings() {
  const [vendorId, setVendorId] = useState("")
  const [settings, setSettings] = useState<Settings | null>(null)
  const [message, setMessage] = useState("")
  const [error, setError] = useState("")
  useEffect(() => { (async () => { try { const identity = await api<Identity>("/api/v1/marketplace/me"); if (!identity.vendor) throw new Error("Vendor access is not configured"); setVendorId(identity.vendor.id); setSettings(await api<Settings>(`/api/v1/marketplace/vendors/${identity.vendor.id}/payment-settings`)) } catch (e) { setError(e instanceof Error ? e.message : "Unable to load settings") } })() }, [])
  async function save() { if (!settings) return; try { setSettings(await api<Settings>(`/api/v1/marketplace/vendors/${vendorId}/payment-settings`, { method: "PATCH", body: JSON.stringify(settings) })); setMessage("Payment settings saved") } catch (e) { setError(e instanceof Error ? e.message : "Unable to save settings") } }
  const links = [{ label: "Dashboard", href: "/vendor/dashboard" }, { label: "Products", href: "/vendor/products" }, { label: "Orders", href: "/vendor/orders" }, { label: "Delivery partners", href: "/vendor/delivery-partners" }, { label: "Payments", href: "/vendor/payments" }, { label: "Settings", href: "/vendor/settings" }]
  return <PortalShell title="Vendor settings" subtitle="Manage your business details and direct payment options." links={links}>{message && <StateMessage>{message}</StateMessage>}{error && <StateMessage error>{error}</StateMessage>}{settings && <section className="portal-panel"><div className="portal-form"><label>Business name<input value={settings.name} onChange={(event) => setSettings({ ...settings, name: event.target.value })} /></label><label>Business image URL<input value={settings.imageUrl || ""} onChange={(event) => setSettings({ ...settings, imageUrl: event.target.value || null })} placeholder="https://..." /></label><label>Contact phone<input value={settings.contactPhone || ""} onChange={(event) => setSettings({ ...settings, contactPhone: event.target.value || null })} /></label><label>Contact email<input type="email" value={settings.contactEmail || ""} onChange={(event) => setSettings({ ...settings, contactEmail: event.target.value || null })} /></label><label>Business address<textarea value={settings.address || ""} onChange={(event) => setSettings({ ...settings, address: event.target.value || null })} /></label><label>UPI ID<input value={settings.upiId || ""} onChange={(event) => setSettings({ ...settings, upiId: event.target.value || null })} placeholder="vendor@upi" /></label><label>UPI display/business name<input value={settings.paymentDisplayName || ""} onChange={(event) => setSettings({ ...settings, paymentDisplayName: event.target.value || null })} /></label><label>QR image URL<input value={settings.qrImageUrl || ""} onChange={(event) => setSettings({ ...settings, qrImageUrl: event.target.value || null })} placeholder="https://..." /></label><label>Payment instructions<textarea value={settings.paymentInstructions || ""} onChange={(event) => setSettings({ ...settings, paymentInstructions: event.target.value || null })} /></label><label><input type="checkbox" checked={settings.cashCollectionEnabled} onChange={(event) => setSettings({ ...settings, cashCollectionEnabled: event.target.checked })} /> Cash collection enabled</label><label><input type="checkbox" checked={settings.upiCollectionEnabled} onChange={(event) => setSettings({ ...settings, upiCollectionEnabled: event.target.checked })} /> UPI collection enabled</label><button onClick={save}>Save settings</button></div></section>}</PortalShell>
}
